INSERT INTO students(user_id,register_number,name,email,department_id,program_id,current_semester_id,year,semester,academic_year,status) SELECT u.id,'BITD0049','Akash Joseph','bitd0049@example.test',d.id,p.id,se.id,'II Year','Semester 4','2024-2025','active' FROM users u JOIN departments d ON d.code='CSE' JOIN programs p ON p.code='BE-CSE' JOIN semesters se ON se.semester_number=4 AND se.academic_year_id=(SELECT id FROM academic_years WHERE label='2024-2025') WHERE u.register_number='BITD0049' ON DUPLICATE KEY UPDATE name=VALUES(name),department_id=VALUES(department_id),program_id=VALUES(program_id),current_semester_id=VALUES(current_semester_id),year=VALUES(year),semester=VALUES(semester),academic_year=VALUES(academic_year);
