INSERT INTO achievements(student_id,title,category,achievement_date,description,status) SELECT id,'Synthetic demo: Sports participation','Sports','2026-08-15','Synthetic example record for ATS demonstration; not a BIT student achievement.','Pending' FROM students WHERE register_number='BITD0100' AND NOT EXISTS(SELECT 1 FROM achievements a JOIN students s ON a.student_id=s.id WHERE s.register_number='BITD0100' AND a.title='Synthetic demo: Sports participation');
INSERT INTO certifications(student_id,name,issuer,issue_date,status) SELECT id,'Synthetic demo learning certificate','Demo issuer','2026-08-15','pending' FROM students WHERE register_number='BITD0100' AND NOT EXISTS(SELECT 1 FROM certifications c JOIN students s ON c.student_id=s.id WHERE s.register_number='BITD0100' AND c.name='Synthetic demo learning certificate');
